export function codePackSearch(question, docs=[], limit=14) {
  const q=n(question); const qt=toks(question); if(!q) return []; const hits=[];
  for (const doc of docs) { const pack=codePackForDoc(doc); if(!pack) continue; const entries=[
    ...(pack.sections||[]).map(x=>({kind:'Điều/Phụ lục',page:x.page,label:x.section,title:x.title})),
    ...(pack.formulas||[]).map(x=>({kind:'Công thức',page:x.page,label:x.label,title:`${x.section||''} ${x.title||''}`.trim()})),
    ...(pack.tables||[]).map(x=>({kind:'Bảng',page:x.page,label:`Bảng ${x.number}`,title:x.title,keywords:x.keywords||''}))];
    for (const e of entries) { const hay=n(`${pack.standard} ${(pack.aliases||[]).join(' ')} ${e.label} ${e.title} ${e.keywords||''}`); let score=0; if(hay.includes(q)||q.includes(hay)) score+=180; for(const t of qt) if(hay.includes(t)) score+=12; if(/cong thuc|formula/.test(q)&&e.kind==='Công thức') score+=30; if(/bang|tra/.test(q)&&e.kind==='Bảng') score+=30; if(score<12) continue; hits.push({docId:doc.id,docName:doc.name,standard:pack.standard,page:e.page,score:1200+score,codePackIndex:true,text:`CODE PACK ${pack.standard} · ${e.kind} ${e.label} · Trang ${e.page}: ${e.title}. Đây là chỉ mục định vị; khi trả lời phải đọc/đối chiếu trang PDF gốc.`}); }
  }
  const seen=new Set(); return hits.sort((a,b)=>b.score-a.score).filter(h=>{const k=`${h.docId}:${h.page}:${h.text}`; if(seen.has(k)) return false; seen.add(k); return true;}).slice(0,limit);
}

export function codePackStats(docs=[]) { const packs=[...new Map(docs.map(codePackForDoc).filter(Boolean).map(p=>[p.id,p])).values()]; return {packs:packs.length, formulas:packs.reduce((s,p)=>s+(p.formulas?.length||0),0), verifiedFormulas:packs.reduce((s,p)=>s+(p.formulas||[]).filter(f=>String(f.status).toLowerCase()==='verified'&&f.computable).length,0), tables:packs.reduce((s,p)=>s+(p.tables?.length||0),0), verifiedTables:packs.reduce((s,p)=>s+(p.tables||[]).filter(t=>String(t.status).toLowerCase()==='verified').length,0), sections:packs.reduce((s,p)=>s+(p.sections?.length||0),0)}; }
